// ✅ ฟังก์ชัน enrich
function enrich(data, plant, quarter, operation) {
    return data.map(item => ({
        ...item,
        plant: plant,
        year_quarter: quarter,
        operation: operation // ซ้ำได้ไม่เป็นไร
    }));
}